/* Water set additions — cards appended after water.js.
   (water.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'water.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('water');
  if (!S) return;
  var extra = [{"name":"James River","rarity":"common","id":"james-river","subtitle":"River","details":"Virginia's James flows about 340 miles to Chesapeake Bay at Hampton Roads; Jamestown, founded in 1607, was settled on its banks.","image":"https://upload.wikimedia.org/wikipedia/commons/d/df/JamesRiverWG.JPG"},{"name":"Savannah River","rarity":"common","id":"savannah-river","subtitle":"River","details":"The Savannah forms most of the Georgia-South Carolina border and flows about 300 miles to the Atlantic at the city of Savannah.","image":"https://upload.wikimedia.org/wikipedia/commons/6/61/Savannah_River_Augusta_Canal_Riverwatch_Pkwy_2.jpg"},{"name":"Altamaha River","rarity":"common","id":"altamaha-river","subtitle":"River","details":"Formed where Georgia's Oconee and Ocmulgee meet, the Altamaha flows 137 miles undammed to the Atlantic near Darien.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6f/Altamaha_River_from_bridge.jpg"},{"name":"Pee Dee River","rarity":"common","id":"pee-dee-river","subtitle":"River","details":"Born as North Carolina's Yadkin River, it becomes the Pee Dee in South Carolina and empties into Winyah Bay on the Atlantic.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0e/Shadfishing8418.JPG"},{"name":"Roanoke River","rarity":"common","id":"roanoke-river","subtitle":"River","details":"From Virginia's Blue Ridge, the Roanoke flows across North Carolina to Albemarle Sound; its upper reach is also called the Staunton River.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0c/Roanoke_River_in_Wasena%2C_Roanoke%2C_Virginia.jpg"},{"name":"Merrimack River","rarity":"common","id":"merrimack-river","subtitle":"River","details":"New Hampshire's Merrimack turns south into Massachusetts, where its falls powered the great textile mill cities of Lowell and Lawrence.","image":"https://upload.wikimedia.org/wikipedia/commons/9/94/Mouth_Merrimack_River.jpg"},{"name":"Kennebec River","rarity":"common","id":"kennebec-river","subtitle":"River","details":"Maine's Kennebec flows 170 miles from Moosehead Lake to the Atlantic, and its lower reach is tidal far inland to Augusta.","image":"https://upload.wikimedia.org/wikipedia/commons/8/85/KennebecRiverinSomersetCounty.JPG"},{"name":"Penobscot River","rarity":"common","id":"penobscot-river","subtitle":"River","details":"Maine's Penobscot drains the state's largest watershed, flowing from the north woods to Penobscot Bay near Bangor.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c7/Penobscot_River_seen_from_Penobscot_Narrows_Bridge_and_Observatory_%28October_2017%29.jpg"},{"name":"Saint John River","rarity":"common","id":"saint-john-river","subtitle":"River","details":"The Saint John flows 418 miles through Maine and New Brunswick to the Bay of Fundy, where huge tides create the Reversing Falls at its mouth.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2c/FrederictonNB_SaintJohnRiver.jpg"},{"name":"Ottawa River","rarity":"common","id":"ottawa-river","subtitle":"River","details":"The Ottawa River forms much of the Ontario-Quebec border for 1,271 km before joining the St. Lawrence near Montreal.","image":"https://upload.wikimedia.org/wikipedia/commons/9/94/Ottawa-Gatineau.-Portage_Bridge_over_the_Ottawa_River.jpg"},{"name":"Winnipeg River","rarity":"common","id":"winnipeg-river","subtitle":"River","details":"The Winnipeg River flows 235 km northwest from Lake of the Woods at Kenora to Lake Winnipeg in Manitoba; its Cree name means murky water.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cf/Lac_du_Bonnet_MB_2.jpg"},{"name":"Albany River","rarity":"common","id":"albany-river","subtitle":"River","details":"At 982 km, the Albany ties as Ontario's longest river entirely in the province, flowing northeast from Lake St. Joseph to James Bay.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e4/Albany_River.JPG"},{"name":"Moose River","rarity":"common","id":"moose-river","subtitle":"River","details":"Ontario's Moose River is formed where the Mattagami and Missinaibi meet, then flows northeast to James Bay at Moosonee.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d1/Moose_River.JPG"},{"name":"Rupert River","rarity":"common","id":"rupert-river","subtitle":"River","details":"Quebec's Rupert flows from Lake Mistassini, Quebec's largest natural lake, west to Rupert Bay on James Bay.","image":"https://upload.wikimedia.org/wikipedia/commons/0/06/Rupert_North_Road_2.JPG"},{"name":"La Grande River","rarity":"common","id":"la-grande-river","subtitle":"River","details":"Quebec's La Grande flows west to James Bay and was transformed by hydroelectric projects, including the vast Robert-Bourassa reservoir.","image":"https://upload.wikimedia.org/wikipedia/commons/1/15/La_Grande_Rivi%C3%A8re2.jpg"},{"name":"Klamath River","rarity":"common","id":"klamath-river","subtitle":"River","details":"The Klamath flows 257 miles from Upper Klamath Lake in Oregon through the Cascades and Coast Ranges of California to the Pacific.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d0/Klamath_river_California.jpg"},{"name":"Rogue River","rarity":"common","id":"rogue-river","subtitle":"River","details":"Oregon's Rogue runs 215 miles from near Crater Lake to the Pacific at Gold Beach, famed for whitewater rafting and salmon runs.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bb/Rogue_River_Oregon_USA.jpg"},{"name":"Green River","rarity":"common","id":"green-river","subtitle":"River","details":"The Green is the Colorado River's largest tributary, flowing 730 miles from Wyoming's Wind River Range through Utah's canyon country.","image":"https://upload.wikimedia.org/wikipedia/commons/7/76/Mineral-Bottom.jpg"},{"name":"San Juan River","rarity":"common","id":"san-juan-river","subtitle":"River","details":"The San Juan winds from Colorado through the Four Corners region to the Colorado River, carving the deep, looping Goosenecks in Utah.","image":"https://upload.wikimedia.org/wikipedia/commons/6/68/Lower_San_Juan_River.jpg"},{"name":"Lerma River","rarity":"common","id":"lerma-river","subtitle":"River","details":"West-central Mexico's Lerma rises near Toluca and flows through the Bajio farming region to Lake Chapala, Mexico's largest natural lake.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c3/Puente_Viaducto_R%C3%ADo_Lerma.JPG"},{"name":"River Severn","rarity":"common","id":"river-severn","subtitle":"River","details":"Great Britain's longest river, the Severn flows 220 miles from Plynlimon in Wales to the Bristol Channel and is known for its tidal bore.","image":"https://upload.wikimedia.org/wikipedia/commons/6/69/SevernFromCastleCB.JPG"},{"name":"River Trent","rarity":"common","id":"river-trent","subtitle":"River","details":"England's Trent flows 185 miles through the Midlands and Nottingham, then joins the Ouse to form the Humber estuary.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a9/River_Trent_-_geograph.org.uk_-_6470987.jpg"},{"name":"River Shannon","rarity":"common","id":"river-shannon","subtitle":"River","details":"Ireland's longest river, the Shannon flows 360 km from the Shannon Pot in County Cavan to its Atlantic estuary below Limerick.","image":"https://upload.wikimedia.org/wikipedia/commons/7/78/River_Shannon_from_Drumsna_bridge.jpg"},{"name":"River Tay","rarity":"common","id":"river-tay","subtitle":"River","details":"Scotland's longest river, the Tay flows through Loch Tay and Perth to the North Sea and carries more water than any other UK river.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7b/St._Matthew%27s_Church_and_Smeaton%27s_Bridge.jpg"},{"name":"River Clyde","rarity":"common","id":"river-clyde","subtitle":"River","details":"The Clyde flows 106 miles across southern Scotland through Glasgow, once a world shipbuilding giant, to the Firth of Clyde.","image":"https://upload.wikimedia.org/wikipedia/commons/0/08/River_Clyde_in_Glasgow_-_aerial_-_2025-04-17_01.jpg"},{"name":"River Tweed","rarity":"common","id":"river-tweed","subtitle":"River","details":"The Tweed flows 97 miles from the Scottish Borders hills to the North Sea at Berwick, forming part of the Scotland-England border.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ee/The_River_Tweed_at_Abbotsford_-_geograph.org.uk_-_1545874.jpg"},{"name":"Guadalquivir River","rarity":"common","id":"guadalquivir-river","subtitle":"River","details":"Andalusia's Guadalquivir flows past Cordoba and Seville, and is navigable from the Gulf of Cadiz upriver to Seville.","image":"https://upload.wikimedia.org/wikipedia/commons/4/45/Guadalquivir1.jpg"},{"name":"Guadiana River","rarity":"common","id":"guadiana-river","subtitle":"River","details":"The Guadiana flows 818 km, forming long stretches of the Spain-Portugal border, before reaching the Gulf of Cadiz.","image":"https://upload.wikimedia.org/wikipedia/commons/4/41/Guadiana_river.jpg"},{"name":"Tagus River","rarity":"common","id":"tagus-river","subtitle":"River","details":"The Tagus, Iberia's longest river at 1,007 km, flows from Spain through Toledo and Lisbon in Portugal to the Atlantic.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d4/Puente_de_San_Mart%C3%ADn._Toledo%2C_Spain.jpg"},{"name":"Garonne River","rarity":"common","id":"garonne-river","subtitle":"River","details":"The Garonne rises in Spain's Pyrenees, flows through Toulouse and Bordeaux, then joins the Dordogne to form the Gironde estuary.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ea/Bordeaux_port_de_la_lune_01.jpg"},{"name":"Tiber River","rarity":"common","id":"tiber-river","subtitle":"River","details":"Italy's Tiber flows 406 km through Rome, past Tiber Island, to the Tyrrhenian Sea at Ostia; Rome was founded on its banks.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8b/PonteSantAngeloRom.jpg"},{"name":"Sava River","rarity":"common","id":"sava-river","subtitle":"River","details":"The Sava is the Danube's largest tributary by water volume, flowing through Ljubljana, Zagreb and Belgrade, where it joins the Danube.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ed/Sava_River_and_Gazela_Bridge_%28Belgrade%29.jpg"},{"name":"Drava River","rarity":"common","id":"drava-river","subtitle":"River","details":"The Drava flows east from the Alps in Italy through Austria, Slovenia and Croatia to join the Danube near Osijek, Croatia.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fa/River_Drava_%2829799981721%29.jpg"},{"name":"Tisza River","rarity":"common","id":"tisza-river","subtitle":"River","details":"The Tisza rises in Ukraine's Carpathians, crosses Hungary's Great Plain, and joins the Danube in Serbia near Titel.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4c/Szeged-tisza3.jpg"},{"name":"Wei River","rarity":"common","id":"wei-river","subtitle":"River","details":"The Wei is the Yellow River's largest tributary, flowing east across Shaanxi past Xi'an through the fertile Guanzhong Plain.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d2/Full_View_of_Wei_River_in_Xianyang_2012-09.jpg"},{"name":"Gan River","rarity":"common","id":"gan-river","subtitle":"River","details":"Jiangxi's Gan River flows north for most of the province's length and empties into Poyang Lake, China's largest freshwater lake.","image":"https://upload.wikimedia.org/wikipedia/commons/2/23/Ganzhou_Yuhong_Ta_2016.06.17_10-02-10.jpg"},{"name":"Xiang River","rarity":"common","id":"xiang-river","subtitle":"River","details":"Hunan's main river, the Xiang flows north past Changsha into Dongting Lake, giving Hunan its Chinese abbreviation, Xiang.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f9/Changsha_section_of_the_Xiang_River_2023103003.jpg"},{"name":"Jialing River","rarity":"common","id":"jialing-river","subtitle":"River","details":"The Jialing winds through deep gorges in Sichuan before joining the Yangtze River at Chongqing.","image":"https://upload.wikimedia.org/wikipedia/commons/6/61/Jialing_river.jpg"},{"name":"Songhua River","rarity":"common","id":"songhua-river","subtitle":"River","details":"The Songhua flows across northeast China past Harbin to join the Amur River, and its basin is a major grain-growing region.","image":"https://upload.wikimedia.org/wikipedia/commons/7/73/SonghuaRiver_ASTER_20020401.jpg"},{"name":"Liao River","rarity":"common","id":"liao-river","subtitle":"River","details":"The Liao flows across the Manchurian plain of northeast China to the Bohai Sea, giving Liaoning province its name.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6e/%E7%9B%98%E9%94%A6%E8%8A%A6%E8%8B%87%E8%8D%A1.JPG"},{"name":"Yalu River","rarity":"common","id":"yalu-river","subtitle":"River","details":"The Yalu forms the border between China and North Korea, flowing about 850 km from Mount Paektu to Korea Bay in the Yellow Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/4/47/%E5%B7%A1%E9%81%93%E5%B7%A5%E5%87%BA%E5%93%81_photo_by_Xundaogong_-_panoramio_%2866%29.jpg"},{"name":"Tarim River","rarity":"common","id":"tarim-river","subtitle":"River","details":"China's longest inland river, the Tarim flows east along the Taklamakan Desert's northern edge in Xinjiang and never reaches the sea.","image":"https://upload.wikimedia.org/wikipedia/commons/2/20/20240321_Aerial_view_of_Tarim_River_in_Xayar_County.jpg"},{"name":"Ili River","rarity":"common","id":"ili-river","subtitle":"River","details":"The Ili flows from China's Xinjiang into Kazakhstan, where its broad delta enters Lake Balkhash, one of Asia's largest lakes.","image":"https://upload.wikimedia.org/wikipedia/commons/4/46/River-ili-2.jpg"},{"name":"Narmada River","rarity":"common","id":"narmada-river","subtitle":"River","details":"The Narmada flows west 1,312 km between the Vindhya and Satpura ranges to the Arabian Sea, unlike most big Indian rivers, which flow east.","image":"https://upload.wikimedia.org/wikipedia/commons/2/22/Narmada_River_Jabalpur_India.jpg"},{"name":"Tapti River","rarity":"common","id":"tapti-river","subtitle":"River","details":"The Tapti is one of India's few major west-flowing rivers, running about 724 km from the Satpura Range to the Arabian Sea near Surat.","image":"https://upload.wikimedia.org/wikipedia/commons/1/11/Tapti_River%2C_Cable_bridge%2C_Surat.jpg"},{"name":"Mahanadi River","rarity":"common","id":"mahanadi-river","subtitle":"River","details":"The Mahanadi flows 858 km from Chhattisgarh through Odisha to the Bay of Bengal; its Hirakud Dam is among the world's longest dams.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6c/Mahanadi_from_Banki.jpg"},{"name":"Okavango River","rarity":"common","id":"okavango-river","subtitle":"River","details":"The Okavango starts in Angola's highlands and never reaches the sea, spreading instead into a vast inland delta in Botswana's Kalahari.","image":"https://upload.wikimedia.org/wikipedia/commons/d/de/Namibia_Okavango_2.jpg"},{"name":"Chari River","rarity":"common","id":"chari-river","subtitle":"River","details":"The Chari flows north from the Central African Republic through Chad and supplies most of the water that feeds Lake Chad.","image":"https://upload.wikimedia.org/wikipedia/commons/5/52/Chari_River.jpg"},{"name":"Benue River","rarity":"common","id":"benue-river","subtitle":"River","details":"The Benue, a major tributary of the Niger, flows from Cameroon across Nigeria to join the Niger at Lokoja.","image":"https://upload.wikimedia.org/wikipedia/commons/5/53/Benue_10.38241E_8.69279N.jpg"},{"name":"Kunene River","rarity":"common","id":"kunene-river","subtitle":"River","details":"The Kunene forms much of the Angola-Namibia border and drops over Epupa Falls before reaching the Atlantic on the desert coast.","image":"https://upload.wikimedia.org/wikipedia/commons/2/29/%C5%98eka_Kunene_River%2C_vodop%C3%A1dy_Epupa_Falls_-_Namibie%2C_Angola_-_panoramio.jpg"},{"name":"Rufiji River","rarity":"common","id":"rufiji-river","subtitle":"River","details":"Tanzania's largest river, the Rufiji flows to the Indian Ocean opposite Mafia Island; its delta holds East Africa's largest mangrove forest.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c8/SelousSandRivers.jpg"},{"name":"Tana River","rarity":"common","id":"tana-river","subtitle":"River","details":"Kenya's longest river, the Tana flows about 1,000 km from Mount Kenya and the Aberdares to the Indian Ocean, powering hydroelectric dams.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0d/DM-SD-01-06042.jpg"},{"name":"Shebelle River","rarity":"common","id":"shebelle-river","subtitle":"River","details":"Rising in Ethiopia's highlands, the Shebelle crosses Somalia past Mogadishu, then usually fades into wetlands before reaching the Jubba River.","image":"https://upload.wikimedia.org/wikipedia/commons/1/18/ATMIS_Support_in_Beletweyne.jpg"},{"name":"Jubba River","rarity":"common","id":"jubba-river","subtitle":"River","details":"The Jubba flows from Ethiopia's highlands across southern Somalia to the Indian Ocean near Kismayo, one of Somalia's only perennial rivers.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8c/Jubba_River_in_Goobweyn.jpg"},{"name":"Araguaia River","rarity":"common","id":"araguaia-river","subtitle":"River","details":"Brazil's Araguaia, a Tocantins tributary, splits mid-course around Bananal Island, the world's largest river island.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9f/Rio_araguaia.jpg"},{"name":"Xingu River","rarity":"common","id":"xingu-river","subtitle":"River","details":"One of the Amazon's largest clearwater tributaries, flowing north from Brazil's central highlands across rapids and rocky channels to the Amazon.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5d/Rio_Xingu_-_Altamira-PA_01.jpg"},{"name":"Tapajós River","rarity":"common","id":"tapajos-river","subtitle":"River","details":"A clearwater Amazon tributary with greenish, low-sediment water; its meeting with the muddy Amazon at Santarém forms a sharp visible line.","image":"https://upload.wikimedia.org/wikipedia/commons/4/45/Encontro_das_aguas_dos_rios_Tapaj%C3%B3s_e_Amazonas_em_Santar%C3%A9m_Par%C3%A1.jpg"},{"name":"Purus River","rarity":"common","id":"purus-river","subtitle":"River","details":"One of the Amazon's longest tributaries, winding in endless meanders from Peru through low, seasonally flooded forest to the Amazon in Brazil.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fa/Purus.jpg"},{"name":"Juruá River","rarity":"common","id":"jurua-river","subtitle":"River","details":"Among the most sinuous rivers in the Amazon basin: meanders make up about two-thirds of its course from Peru's highlands to the Amazon.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8d/City_of_Carauari%2C_the_Juru%C3%A1_River_and_its_tributaries%2C_taken_from_the_International_Space_Station.jpg"},{"name":"Japurá River","rarity":"common","id":"japura-river","subtitle":"River","details":"Known as the Caquetá in Colombia, it crosses into Brazil as the Japurá and joins the Amazon, draining a vast stretch of western Amazon rainforest.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2c/Caquet%C3%A1_River.jpg"},{"name":"Putumayo River","rarity":"common","id":"putumayo-river","subtitle":"River","details":"Forms much of Colombia's border with Ecuador and Peru; in Brazil it is called the Içá before joining the upper Amazon, the Solimões.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f2/K_Rio_Putumayo_0306_001_%2817289214536%29.jpg"},{"name":"Pilcomayo River","rarity":"common","id":"pilcomayo-river","subtitle":"River","details":"The Paraguay River's longest western tributary, rising in Bolivia's Andes and crossing the Gran Chaco, where heavy silt repeatedly plugs its channel.","image":"https://upload.wikimedia.org/wikipedia/commons/8/86/R%C3%ADo_Pilcomayo%2C_%C3%81rea_natural_de_manejo_integrado_Aguarag%C3%BCe_-_Bolivia.jpg"},{"name":"Bermejo River","rarity":"common","id":"bermejo-river","subtitle":"River","details":"Its name means 'red river' for its sediment-laden water; it flows from Bolivia across Argentina's Gran Chaco to join the Paraguay River.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bc/Bermejo_River_seen_from_Mansilla-Eva_Per%C3%B3n_bridge_to_the_South.JPG"},{"name":"Madre de Dios River","rarity":"common","id":"madre-de-dios-river","subtitle":"River","details":"Rises in Peru's Andes and joins the Beni River in Bolivia, forming part of the Madeira system, the Amazon's largest tributary network.","image":"https://upload.wikimedia.org/wikipedia/commons/7/77/Madre_de_Dios_Boca_Manu.jpg"},{"name":"Flinders River","rarity":"common","id":"flinders-river","subtitle":"River","details":"The longest river lying entirely in Queensland, flowing northwest from the Great Dividing Range across the Gulf Country to the Gulf of Carpentaria.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3c/Looking_downstream_along_the_Flinders_River_while_crossing_on_the_Burke_Developmental_Road%2C_Normanton%2C_June_2019_01.jpg"},{"name":"Fly River","rarity":"common","id":"fly-river","subtitle":"River","details":"Flows south across Papua New Guinea's lowlands to a vast tidal estuary on the Gulf of Papua, where tides push far upstream.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4e/Fly_River.PNG"},{"name":"Sepik River","rarity":"common","id":"sepik-river","subtitle":"River","details":"Papua New Guinea's longest river, meandering through swamps and rainforest to the Bismarck Sea — unusually, it forms no delta at its mouth.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2f/Sepik-sediment-new.png"},{"name":"Waikato River","rarity":"common","id":"waikato-river","subtitle":"River","details":"New Zealand's longest river at 425 km, flowing from Lake Taupō through the North Island to the Tasman Sea at Port Waikato.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c0/Waikato_river_750px.jpg"},{"name":"Clutha River","rarity":"common","id":"clutha-river","subtitle":"River","details":"New Zealand's highest-volume river, draining Lake Wānaka through Otago's gold-rush country in swift, turquoise water to the Pacific Ocean.","image":"https://upload.wikimedia.org/wikipedia/commons/8/88/Upper_Clutha_Valley.jpg"},{"name":"Murrumbidgee River","rarity":"common","id":"murrumbidgee-river","subtitle":"River","details":"A major tributary of the Murray, rising in Australia's Snowy Mountains and flowing west across New South Wales plains to join the Murray.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b8/Murrumbidgee_River_-_October_2008.jpg"},{"name":"Cooper Creek","rarity":"common","id":"cooper-creek","subtitle":"River","details":"Formed where the Thomson and Barcoo rivers meet in Channel Country; its floodwaters spread over vast plains and reach Lake Eyre only in big floods.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b5/Channel_Country%2C_Cooper_Creek%2C_Windorah.jpg"},{"name":"Burdekin River","rarity":"common","id":"burdekin-river","subtitle":"River","details":"One of Queensland's great rivers, draining a huge inland catchment east to Upstart Bay on the Coral Sea, with flows that swing wildly by season.","image":"https://upload.wikimedia.org/wikipedia/commons/8/80/BurdekinBridgeNov022024_02.jpg"},{"name":"Lake Winnipesaukee","rarity":"common","id":"lake-winnipesaukee","subtitle":"Lake","details":"New Hampshire's largest lake, dotted with more than 250 islands and ringed by a shoreline of about 288 miles at the foothills of the White Mountains.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0a/Mtmajorsummitbig-2007-1022a.jpg"},{"name":"Moosehead Lake","rarity":"common","id":"moosehead-lake","subtitle":"Lake","details":"Maine's largest lake, a sprawling North Woods water with over 80 islands; seen from above, its shape is said to resemble a moose's head.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a2/Mouth_of_Moose_River_from_Mount_Kineo.jpg"},{"name":"Lake George","rarity":"common","id":"lake-george","subtitle":"Lake","details":"A long, narrow Adirondack lake in New York, about 32 miles end to end, long nicknamed the 'Queen of American Lakes' for its clear water and islands.","image":"https://upload.wikimedia.org/wikipedia/commons/e/eb/Lake_George_aerial_view_2025.jpg"},{"name":"Lake Placid","rarity":"common","id":"lake-placid","subtitle":"Lake","details":"An Adirondack lake in New York overlooked by Whiteface Mountain, sharing its name with the neighbouring village in the High Peaks region.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4e/Whiteface-Lake_Placid_View.jpg"},{"name":"Seneca Lake","rarity":"common","id":"seneca-lake","subtitle":"Lake","details":"The deepest Finger Lake at 618 feet, with its bottom well below sea level; glacially carved and the largest of the lakes by surface area.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a4/Autumn_at_Seneca_Lake_-_New_York_-_US_-_2019.jpg"},{"name":"Cayuga Lake","rarity":"common","id":"cayuga-lake","subtitle":"Lake","details":"The longest Finger Lake at about 38 miles, with Ithaca at its southern end; its deep, glacially carved basin drops well below sea level.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e8/Cayuga_Lake%2C_May_2025.jpg"},{"name":"Lake Coeur d'Alene","rarity":"common","id":"lake-coeur-dalene","subtitle":"Lake","details":"A northern Idaho lake fed by the Coeur d'Alene and St. Joe rivers, draining westward through the Spokane River toward the Columbia.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cc/Lakecoeurdalenebig.jpg"},{"name":"Flathead Lake","rarity":"common","id":"flathead-lake","subtitle":"Lake","details":"The largest natural freshwater lake by surface area west of the Mississippi in the contiguous United States, carved by glaciers in Montana.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b5/Flathead_Lake.jpeg"},{"name":"Lake Chelan","rarity":"common","id":"lake-chelan","subtitle":"Lake","details":"A fjord-like Washington lake over 50 miles long and 1,486 feet deep — the third-deepest lake in the United States, with its floor below sea level.","image":"https://upload.wikimedia.org/wikipedia/commons/6/62/Stehekin_Chelan.JPG"},{"name":"Lake Okanagan","rarity":"common","id":"lake-okanagan","subtitle":"Lake","details":"A long, deep British Columbia lake famed in local legend as home of Ogopogo, a lake creature said to inhabit its waters.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c6/Peachland%2C_British_Columbia.jpg"},{"name":"Mono Lake","rarity":"common","id":"mono-lake","subtitle":"Lake","details":"An ancient, highly saline California lake with no outlet, famous for its tufa towers — limestone spires grown where springs met alkaline water.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a0/Mono_Lake_aerial.jpg"},{"name":"Pyramid Lake","rarity":"common","id":"pyramid-lake","subtitle":"Lake","details":"Nevada's desert lake is the largest remnant of Ice Age Lake Lahontan and the terminus of the Truckee River, named for a pyramid-shaped tufa rock.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e1/The_pyramid.jpg"},{"name":"Utah Lake","rarity":"common","id":"utah-lake","subtitle":"Lake","details":"Utah's largest freshwater lake, a broad, shallow lake west of Provo that drains north through the Jordan River into the Great Salt Lake.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b0/Utahlake_oli_2017171_lrg.jpeg"},{"name":"Jackson Lake","rarity":"common","id":"jackson-lake","subtitle":"Lake","details":"A natural Wyoming lake on the Snake River, enlarged by a dam, lying directly beneath the jagged eastern front of the Teton Range.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b0/Colter_bay_boats_20100822_080110_1.jpg"},{"name":"Iliamna Lake","rarity":"common","id":"iliamna-lake","subtitle":"Lake","details":"Alaska's largest lake, draining through the Kvichak River to Bristol Bay — a watershed famed for its sockeye salmon runs.","image":"https://upload.wikimedia.org/wikipedia/commons/6/61/Iliamna_Lake_by_Sentinel-2.jpg"},{"name":"Glenn Springs Lake","rarity":"common","id":"glenn-springs-lake","subtitle":"Lake","details":"A 310-acre TWRA fishing lake in Tipton County near Drummonds, Tennessee — small water with a fishing pier, and a local favorite close to home.","image":"assets/sets/water/images/glenn-springs-lake.png"},{"name":"Windermere","rarity":"common","id":"windermere","subtitle":"Lake","details":"England's largest natural lake, a long ribbon about 10.5 miles long in the Lake District, formed in a glacial valley after the last ice age.","image":"https://upload.wikimedia.org/wikipedia/commons/2/20/Windermere_Lake_District_from_hill.JPG"},{"name":"Lough Neagh","rarity":"common","id":"lough-neagh","subtitle":"Lake","details":"The largest lake by surface area in the British Isles, a broad, shallow Northern Ireland lough supplying much of the region's drinking water.","image":"https://upload.wikimedia.org/wikipedia/commons/2/27/Lough_Neagh_by_Sentinel-2.jpg"},{"name":"Loch Lomond","rarity":"common","id":"loch-lomond","subtitle":"Lake","details":"Great Britain's largest lake by surface area, straddling Scotland's Highland Boundary Fault — deep and narrow in the north, wide in the south.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a8/Loch_Lomond_2013_2.JPG"},{"name":"Lake Annecy","rarity":"common","id":"lake-annecy","subtitle":"Lake","details":"A glacial lake in the French Alps, ringed by mountains with the town of Annecy at its northern end, where its water drains toward the Rhône system.","image":"https://upload.wikimedia.org/wikipedia/commons/3/38/Aerial_image_of_Lake_Annecy_%28view_from_the_south%29.jpg"},{"name":"Lake Zurich","rarity":"common","id":"lake-zurich","subtitle":"Lake","details":"A crescent-shaped Swiss lake with the city of Zurich at its northwestern end, where the lake narrows and flows out as the Limmat River.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9e/Pfannenstiel_-_Z%C3%BCrichsee_-_Sihltal_-_Albis_Baldern_IMG_5316.jpg"},{"name":"Lake Lugano","rarity":"common","id":"lake-lugano","subtitle":"Lake","details":"A glacial lake straddling Switzerland and Italy, its branching arms winding between steep mountains between Lakes Como and Maggiore.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4d/LagoDiLugano.jpg"},{"name":"Lake Mälaren","rarity":"common","id":"lake-malaren","subtitle":"Lake","details":"Sweden's third-largest lake, stretching west from Stockholm, where it drains into the Baltic Sea; its islands hold the Viking Age site of Birka.","image":"https://upload.wikimedia.org/wikipedia/commons/3/39/M%C3%A4larsee.jpg"},{"name":"Lake Päijänne","rarity":"common","id":"lake-paijanne","subtitle":"Lake","details":"Finland's second-largest lake, a long, narrow water stretching north from near Lahti, known for deep basins and hundreds of islands.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b3/P%C3%A4ij%C3%A4nne_and_p%C3%A4ij%C3%A4tsalo.jpg"},{"name":"Lake Bled","rarity":"common","id":"lake-bled","subtitle":"Lake","details":"A Slovenian glacial lake whose tiny island carries a church with a wishing bell, reached by traditional flat-bottomed pletna boats.","image":"https://upload.wikimedia.org/wikipedia/commons/8/84/Lake_Bled_from_the_Mountain.jpg"},{"name":"Lake Trasimeno","rarity":"common","id":"lake-trasimeno","subtitle":"Lake","details":"A shallow Italian lake in Umbria; on its northern shore in 217 BCE, Hannibal ambushed and destroyed a Roman army in the fog.","image":"https://upload.wikimedia.org/wikipedia/commons/6/60/Lago_Trasimeno_wide_view.jpg"},{"name":"Lake Iseo","rarity":"common","id":"lake-iseo","subtitle":"Lake","details":"A Lombardy lake in Italy dominated by Monte Isola, a large inhabited island rising from its centre, ringed by steep mountains.","image":"https://upload.wikimedia.org/wikipedia/commons/9/96/LagoIseo.jpg"},{"name":"Lake Neuchâtel","rarity":"common","id":"lake-neuchatel","subtitle":"Lake","details":"The largest lake lying entirely within Switzerland, a long, shallow lake at the foot of the Jura mountains, linked by canal to neighbouring lakes.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8a/Lac_de_neuchatel.jpg"},{"name":"Salton Sea","rarity":"common","id":"salton-sea","subtitle":"Lake","details":"California's present Salton Sea dates from 1905, when the Colorado River breached an irrigation intake and poured into the Salton Sink for two years.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ae/ISS021-E-8254_-_View_of_California.jpg"},{"name":"Lake Chapala","rarity":"common","id":"lake-chapala","subtitle":"Lake","details":"Mexico's largest freshwater lake, a broad, shallow lake between Jalisco and Michoacán fed mainly by the Lerma River.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4e/Beach-blue-sky-chapala-545892.jpg"},{"name":"Lake Atitlán","rarity":"common","id":"lake-atitlan","subtitle":"Lake","details":"A Guatemalan caldera lake and Central America's deepest at about 340 m, ringed by three volcanoes and Maya villages on its shores.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c8/Lago_de_Atitlan_seen_from_orbit.jpg"},{"name":"Lake Argentino","rarity":"common","id":"lake-argentino","subtitle":"Lake","details":"Argentina's largest freshwater lake, a milky turquoise Patagonian lake fed by glaciers, including Perito Moreno, which calves ice into its arms.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c7/Lake_Argentino_northern_arm_Lago_Argentino_Brazo_Norte_Patagonia_Argentina_Luca_Galuzzi_2005.JPG"},{"name":"Lake Nahuel Huapi","rarity":"common","id":"lake-nahuel-huapi","subtitle":"Lake","details":"A deep, branching glacial lake in Argentina's Andes, with fjord-like arms and the lakeside town of Bariloche on its southern shore.","image":"https://upload.wikimedia.org/wikipedia/commons/9/92/View_from_the_Golf_course_at_Llao_Llao.jpg"},{"name":"Lake Llanquihue","rarity":"common","id":"lake-llanquihue","subtitle":"Lake","details":"One of Chile's largest lakes, lying in the shadow of the near-perfect cone of Osorno Volcano in the Chilean Lakes District.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a6/Volc%C3%A1n_Osorno_y_lago_Llanquihue_desde_el_sector_Los_Riscos.jpg"},{"name":"Lake Nakuru","rarity":"common","id":"lake-nakuru","subtitle":"Lake","details":"A shallow, highly alkaline Rift Valley lake in Kenya whose algae-rich shores draw large flocks of lesser flamingos and other waterbirds.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9b/Lake-Nakuru-Baboon-Hill-View.JPG"},{"name":"Lake Naivasha","rarity":"common","id":"lake-naivasha","subtitle":"Lake","details":"A freshwater Rift Valley lake in Kenya — a rarity among its salty neighbours — fringed with papyrus and home to hippos and fish eagles.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fd/Naivasha_lake.jpg"},{"name":"Lake Bunyonyi","rarity":"common","id":"lake-bunyonyi","subtitle":"Lake","details":"A Ugandan highland lake dotted with 29 islands among terraced hills; its name is often translated as 'place of many little birds.'","image":"https://upload.wikimedia.org/wikipedia/commons/a/af/Lake_Bunyonyi_%288146148093%29.jpg"},{"name":"Lake Chilwa","rarity":"common","id":"lake-chilwa","subtitle":"Lake","details":"A shallow Malawian lake with no outlet, whose shoreline shifts dramatically with rainfall — in severe droughts it has shrunk drastically.","image":"https://upload.wikimedia.org/wikipedia/commons/4/44/Punter_on_Lake_Chilwa%2C_Malawi.jpg"},{"name":"Lake Rotorua","rarity":"common","id":"lake-rotorua","subtitle":"Lake","details":"A volcanic caldera lake in New Zealand's North Island, famed for geothermal activity and the lakeside city of Rotorua on its southern shore.","image":"https://upload.wikimedia.org/wikipedia/commons/5/58/Lake_Rotorua.jpg"},{"name":"Lake Tekapo","rarity":"common","id":"lake-tekapo","subtitle":"Lake","details":"Its vivid turquoise color comes from fine glacial rock flour suspended in water fed by Southern Alps glaciers in the Mackenzie Basin.","image":"https://upload.wikimedia.org/wikipedia/commons/6/65/LakeTekapoNov242024_05.jpg"},{"name":"Lake Pukaki","rarity":"common","id":"lake-pukaki","subtitle":"Lake","details":"A glacial lake in the Mackenzie Basin with striking blue water and clear views north to Aoraki / Mount Cook, New Zealand's tallest peak.","image":"https://upload.wikimedia.org/wikipedia/commons/0/08/LakePukakiNov232024_01.jpg"},{"name":"Lake Manapouri","rarity":"common","id":"lake-manapouri","subtitle":"Lake","details":"New Zealand's second-deepest lake, at 444 meters, with an underground hydroelectric power station beneath its West Arm.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3e/Lake_Manapouri_towards_Turret_Range_and_West_Arm.jpg"},{"name":"Lake Tai","rarity":"common","id":"lake-tai","subtitle":"Lake","details":"China's third-largest freshwater lake, a vast shallow lake near Wuxi and Suzhou known for Taihu scholar's rocks and lakeside gardens.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7d/Lake_Tai_1.jpg"},{"name":"Lake Dongting","rarity":"common","id":"lake-dongting","subtitle":"Lake","details":"China's second-largest freshwater lake, a Yangtze floodplain lake in Hunan that swells and shrinks dramatically with the seasons.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5c/Waters_of_central_China.jpg"},{"name":"Ross Sea","rarity":"common","id":"ross-sea","subtitle":"Sea","details":"The world's southernmost sea, bordering Antarctica beneath the Ross Ice Shelf and rich with penguins, seals and whales.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b5/Ross_Sea%2C_Summer_2016_25.jpg"},{"name":"Weddell Sea","rarity":"common","id":"weddell-sea","subtitle":"Sea","details":"An Antarctic sea where Ernest Shackleton's ship Endurance was trapped and crushed by pack ice in 1915.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e5/ISS011-E-12089_-_View_of_the_Weddell_Sea.jpg"},{"name":"Amundsen Sea","rarity":"common","id":"amundsen-sea","subtitle":"Sea","details":"A remote West Antarctic sea into which the fast-changing Pine Island and Thwaites glaciers drain.","image":"https://upload.wikimedia.org/wikipedia/commons/1/19/Before_calving_at_Pine_Island_Bay.jpg"},{"name":"Bellingshausen Sea","rarity":"common","id":"bellingshausen-sea","subtitle":"Sea","details":"A sea west of the Antarctic Peninsula, named for explorer Fabian Gottlieb von Bellingshausen, who explored the region in 1821.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e2/A_mixture_of_sea_ice_%2851062594113%29.jpg"},{"name":"Davis Sea","rarity":"common","id":"davis-sea","subtitle":"Sea","details":"An East Antarctic sea between the West and Shackleton ice shelves, fronting Mirny Station on the Antarctic coast.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ae/Another_Iceberg_%28PS141_-_Davis_Sea_and_Antarctica%29.jpg"},{"name":"Lincoln Sea","rarity":"common","id":"lincoln-sea","subtitle":"Sea","details":"The northernmost arm of the Arctic Ocean, north of Ellesmere Island and Greenland, long covered by some of the Arctic's thickest sea ice.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a3/Lincoln_Sea_%28MODIS_2020-07-27%29.jpg"},{"name":"Molucca Sea","rarity":"common","id":"molucca-sea","subtitle":"Sea","details":"A deep sea in Indonesia between Sulawesi and the Maluku Islands, part of the complex island seas of the Malay Archipelago.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7c/Ternate_Island.jpg"},{"name":"Halmahera Sea","rarity":"common","id":"halmahera-sea","subtitle":"Sea","details":"A sea east of Indonesia's Halmahera Island, linking the Pacific Ocean with the island seas of the Maluku region.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3b/Piaynemo_Island%2C_Raja_Ampat%2C_West_Papua%2C_Indonesia.jpg"},{"name":"Savu Sea","rarity":"common","id":"savu-sea","subtitle":"Sea","details":"A deep Indonesian sea between Timor, Flores and Sumba, an important passage for whales moving between the Pacific and Indian oceans.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e7/LesserSundaIslands_A2003077_0210_250m.jpg"},{"name":"Bali Sea","rarity":"common","id":"bali-sea","subtitle":"Sea","details":"The sea north of Bali and Lombok in Indonesia, stretching east toward Flores beneath busy inter-island ferry routes.","image":"https://upload.wikimedia.org/wikipedia/commons/3/39/Clouds_over_Lombok_Strait%2C_Gili_Islands%2C_West_Nusa_Tenggara%2C_Indonesia.jpg"},{"name":"Koro Sea","rarity":"common","id":"koro-sea","subtitle":"Sea","details":"A sea in the Fiji archipelago named for Koro Island, enclosed by Viti Levu, Vanua Levu and the Lau group.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1c/Kanacea_Island_from_near_Korolevu%2C_Vanua_Balavu%2C_Fiji_1977.jpg"},{"name":"Bohol Sea","rarity":"common","id":"bohol-sea","subtitle":"Sea","details":"Also called the Mindanao Sea, it lies south of Bohol in the Philippines and is visited by whale sharks, dolphins and manta rays.","image":"https://upload.wikimedia.org/wikipedia/commons/4/40/Camiguin_across_Bohol_Sea.jpg"},{"name":"Sargasso Sea","rarity":"common","id":"sargasso-sea","subtitle":"Sea","details":"The only sea with no land shoreline, defined by swirling Atlantic currents and mats of floating sargassum seaweed.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ab/Sargasso_seaweed_detail.jpg"},{"name":"Seto Inland Sea","rarity":"common","id":"seto-inland-sea","subtitle":"Sea","details":"Japan's calm inland sea between Honshu, Shikoku and Kyushu, dotted with thousands of islands and crossed by great bridge systems.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4d/Seto_Inland_Sea.jpg"},{"name":"Bohai Sea","rarity":"common","id":"bohai-sea","subtitle":"Sea","details":"China's innermost sea, a shallow arm of the Yellow Sea nearly enclosed by the Liaodong and Shandong peninsulas.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e9/Seashore_for_Bohai_at_Laolongtou_Site.jpg"},{"name":"Sea of the Hebrides","rarity":"common","id":"sea-of-the-hebrides","subtitle":"Sea","details":"A sea off western Scotland between the mainland and the Outer Hebrides, a summer feeding ground for basking sharks.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c0/Barra%2C_from_over_the_Sea_of_the_Hebrides_-_geograph.org.uk_-_5376466.jpg"},{"name":"Beaufort Sea","rarity":"common","id":"beaufort-sea","subtitle":"Sea","details":"An Arctic sea north of Alaska and Canada's Yukon and Northwest Territories, where the Mackenzie River empties into the ocean.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bf/Beaufort_Sea_Thaw_%28MODIS_2021-05-24%29.jpg"},{"name":"Delaware Bay","rarity":"common","id":"delaware-bay","subtitle":"Bay","details":"The estuary of the Delaware River between Delaware and New Jersey, famous for spring horseshoe crab spawning and migrating shorebirds.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9a/Delawarebaymodis.jpg"},{"name":"Tampa Bay","rarity":"common","id":"tampa-bay","subtitle":"Bay","details":"Florida's largest open-water estuary, a broad bay on the Gulf coast fed by the Hillsborough, Alafia and Manatee rivers.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0b/SUNSHINE_SKYWAY_BRIDGE_ON_TAMPA_BAY_-_panoramio.jpg"},{"name":"Mobile Bay","rarity":"common","id":"mobile-bay","subtitle":"Bay","details":"An Alabama estuary famed for the jubilee, when fish and crabs crowd into shallow shoreline water in summer.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f3/Baie_de_Mobile.jpg"},{"name":"Galveston Bay","rarity":"common","id":"galveston-bay","subtitle":"Bay","details":"A large Texas estuary where the Trinity and San Jacinto rivers meet the Gulf, linked to Houston by a busy ship channel.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f9/Galveston_Bay_Landsat.jpg"},{"name":"Narragansett Bay","rarity":"common","id":"narragansett-bay","subtitle":"Bay","details":"New England's largest estuary, cutting into Rhode Island and lined by Providence, Newport and historic sailing ports.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1e/Rose_Island_Lighthouse_--_Narragansett_Bay_Newport_%28RI%29_September_2018_%2829742460177%29.jpg"},{"name":"Cape Cod Bay","rarity":"common","id":"cape-cod-bay","subtitle":"Bay","details":"A bay of the Gulf of Maine cradled by Cape Cod, where endangered North Atlantic right whales feed in spring.","image":"https://upload.wikimedia.org/wikipedia/commons/a/af/Anchorage_Cape_Cod_Bay.jpg"},{"name":"Penobscot Bay","rarity":"common","id":"penobscot-bay","subtitle":"Bay","details":"Maine's great island-dotted bay at the mouth of the Penobscot River, long prized for lobster fishing and sailing.","image":"https://upload.wikimedia.org/wikipedia/commons/8/89/Penobscot_Bay%2C_Maine.jpg"},{"name":"Monterey Bay","rarity":"common","id":"monterey-bay","subtitle":"Bay","details":"A California bay cut by one of the largest submarine canyons on the U.S. west coast, now a protected marine sanctuary.","image":"https://upload.wikimedia.org/wikipedia/commons/8/83/Monterey_Bay_STS090-705-5.jpg"},{"name":"San Diego Bay","rarity":"common","id":"san-diego-bay","subtitle":"Bay","details":"A crescent-shaped natural harbor in Southern California, sheltered by Point Loma and home to a major U.S. naval presence.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bb/SDBayAreaNASA.jpg"},{"name":"Port Phillip Bay","rarity":"common","id":"port-phillip-bay","subtitle":"Bay","details":"Melbourne's large, mostly shallow bay in Victoria, entered through the narrow and treacherous channel called The Rip.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2e/Melbourne_Across_Port_Philip.jpg"},{"name":"Botany Bay","rarity":"common","id":"botany-bay","subtitle":"Bay","details":"The bay south of Sydney where James Cook first landed in Australia in 1770, at Kurnell on its southern shore.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ec/Sydney_from_Botany_Bay_looking_north_%28aerial%29.jpg"},{"name":"Shark Bay","rarity":"common","id":"shark-bay","subtitle":"Bay","details":"A Western Australian bay famed for living stromatolites at Hamelin Pool and one of the world's largest dugong populations.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7b/Shark_Bay_Phytoplankton_in_Bloom.jpg"},{"name":"Hawke's Bay","rarity":"common","id":"hawkes-bay","subtitle":"Bay","details":"A broad, sweeping bay on the east coast of New Zealand's North Island, fronting the Art Deco city of Napier.","image":"https://upload.wikimedia.org/wikipedia/commons/6/68/Hawke_bay_landsat.jpg"},{"name":"Bay of Islands","rarity":"common","id":"bay-of-islands","subtitle":"Bay","details":"A drowned-valley bay in northern New Zealand containing 144 islands, centered on Paihia, Russell and historic Waitangi.","image":"https://upload.wikimedia.org/wikipedia/commons/3/31/00_4801_Dolphins_-_Bay_of_Islands.jpg"},{"name":"Spencer Gulf","rarity":"common","id":"spencer-gulf","subtitle":"Gulf","details":"A South Australian gulf between the Eyre and Yorke peninsulas, known for winter aggregations of giant Australian cuttlefish near Whyalla.","image":"https://upload.wikimedia.org/wikipedia/commons/7/70/25_Boston_Bay_17.JPG"},{"name":"Long Island Sound","rarity":"common","id":"long-island-sound","subtitle":"Sound","details":"A tidal estuary between Long Island and Connecticut, stretching about 110 miles from New York City toward the Atlantic.","image":"https://upload.wikimedia.org/wikipedia/commons/8/87/Connecticut_Sundown_on_Long_Island_Sound%2C_Mark_Masselli.jpg"},{"name":"Puget Sound","rarity":"common","id":"puget-sound","subtitle":"Sound","details":"Washington's intricate fjord system of inlets and islands, home to Seattle, Tacoma and southern resident orcas.","image":"https://upload.wikimedia.org/wikipedia/commons/0/09/Puget_Sound_by_Sentinel-2%2C_2018-09-28_%28small_version%29.jpg"},{"name":"Pamlico Sound","rarity":"common","id":"pamlico-sound","subtitle":"Sound","details":"The largest lagoon along the North American East Coast, a shallow sound sheltered by North Carolina's Outer Banks barrier islands.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e5/PamlicoSound-EO.JPG"},{"name":"Albemarle Sound","rarity":"common","id":"albemarle-sound","subtitle":"Sound","details":"A large, mostly freshwater estuary in northeastern North Carolina, fed by the Roanoke and Chowan rivers.","image":"https://upload.wikimedia.org/wikipedia/commons/6/66/Albemarle_Sound.jpg"},{"name":"Strait of Messina","rarity":"common","id":"strait-of-messina","subtitle":"Strait","details":"The narrow strait between Sicily and mainland Italy, home to whirlpools that inspired the myths of Scylla and Charybdis.","image":"https://upload.wikimedia.org/wikipedia/commons/3/39/Ferry_Giano_crossing_the_Strait_of_Messina_-_Oct._2009.jpg"},{"name":"Strait of Otranto","rarity":"common","id":"strait-of-otranto","subtitle":"Strait","details":"The strait linking the Adriatic and Ionian seas between Italy and Albania, about 72 kilometers wide at its narrowest.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f1/Otranto_-_Seafront_-_01.jpg"},{"name":"Strait of Bonifacio","rarity":"common","id":"strait-of-bonifacio","subtitle":"Strait","details":"The wild, wind-swept strait between Corsica and Sardinia, guarding the granite cliffs of Bonifacio and the Lavezzi Islands.","image":"https://upload.wikimedia.org/wikipedia/commons/0/05/Santa_Teresa_Gallura_-_Bocche_di_Bonifacio_%2804%29.JPG"},{"name":"Tsugaru Strait","rarity":"common","id":"tsugaru-strait","subtitle":"Strait","details":"The strait between Japan's Honshu and Hokkaido islands, crossed beneath by the 53.9-kilometer Seikan Tunnel.","image":"https://upload.wikimedia.org/wikipedia/commons/2/28/Cape_Tachimachi_viewed_from_the_Tsugaru_Strait.jpg"},{"name":"Luzon Strait","rarity":"common","id":"luzon-strait","subtitle":"Strait","details":"The wide strait between Taiwan and Luzon linking the South China Sea to the Philippine Sea, crossed by many undersea data cables.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5d/Batanes_Island_of_Winds.jpg"},{"name":"Makassar Strait","rarity":"common","id":"makassar-strait","subtitle":"Strait","details":"The deep strait between Borneo and Sulawesi in Indonesia, a major shipping route along the biological divide called the Wallace Line.","image":"https://upload.wikimedia.org/wikipedia/commons/9/93/Manggar_Beach%2C_Balikpapan.jpg"},{"name":"North Channel","rarity":"common","id":"north-channel","subtitle":"Strait","details":"The channel linking the Irish Sea to the Atlantic between Northern Ireland and Scotland, just 19 kilometers wide at its narrowest.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d4/Ferry_boat_ST_SORNEY_of_Rathlin_Island_Ferry_Ltd._arriving_Ballycastle_%282012%29.jpg"},{"name":"Foveaux Strait","rarity":"common","id":"foveaux-strait","subtitle":"Strait","details":"The rough strait between New Zealand's South Island and Stewart Island, famed for its prized Bluff oysters.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b6/Bluff_from_Stewart_Island_ferry.jpg"},{"name":"Hecate Strait","rarity":"common","id":"hecate-strait","subtitle":"Strait","details":"A broad, shallow and often stormy strait in British Columbia between the mainland and the Haida Gwaii archipelago.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cc/HecateStrait%28PittIsland%29.JPG"},{"name":"Juan de Fuca Strait","rarity":"common","id":"juan-de-fuca-strait","subtitle":"Strait","details":"The Pacific outlet of the Salish Sea, forming part of the U.S.-Canada border between Washington and Vancouver Island.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c9/Strait_of_Juan_de_Fuca_by_Sentinel-2%2C_2018-09-28_%28small_version%29.jpg"},{"name":"Beagle Channel","rarity":"common","id":"beagle-channel","subtitle":"Channel","details":"The strait through Tierra del Fuego sailed by HMS Beagle with Charles Darwin aboard, passing the port city of Ushuaia.","image":"https://upload.wikimedia.org/wikipedia/commons/9/93/090111-6_Above_%E3%83%93%E3%83%BC%E3%82%B0%E3%83%AB%E6%B0%B4%E9%81%93.jpg"},{"name":"Golden Gate","rarity":"common","id":"golden-gate","subtitle":"Channel","details":"The strait linking San Francisco Bay to the Pacific Ocean, spanned since 1937 by the Golden Gate Bridge.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bf/Golden_Gate_Bridge_as_seen_from_Battery_East.jpg"},{"name":"Drake Passage","rarity":"common","id":"drake-passage","subtitle":"Passage","details":"The stormy passage between South America's Cape Horn and Antarctica, where the Antarctic Circumpolar Current flows unimpeded by land.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1f/00_0468_Iceberg_-_Drake_Passage.jpg"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
